import argparse
from .core import upload_dataset_to_webdav


# %% ../nbs/01_cli.ipynb 3
def main():
    parser = argparse.ArgumentParser(description="Upload dataset to WebDAV")
    parser.add_argument("--source", required=True, help="Path to local dataset folder")
    parser.add_argument("--label", required=True, help="Dataset label (e.g. 2025_exp01)")
    parser.add_argument("--title", required=True, help="Dataset title")
    parser.add_argument("--source_name", required=True, help="Who collected the data")
    parser.add_argument("--date_collected", required=True, help="Date data was collected")
    parser.add_argument("--description", required=True, help="Short description")
    parser.add_argument("--responsible", required=True, help="Uploader's name")
    parser.add_argument("--username", required=True, help="WebDAV username")
    parser.add_argument("--email", required=True, help="Contact email")
    parser.add_argument("--webdav", default="https://u-drive.unipi.it/remote.php/webdav/RRL/archival_data", help="Base WebDAV URL")
    parser.add_argument("--dry-run", action="store_true", help="Preview only, no upload")
    
    args = parser.parse_args()

    metadata = {
        "title": args.title,
        "source": args.source_name,
        "date_collected": args.date_collected,
        "description": args.description,
        "responsible": args.responsible
    }

    upload_dataset_to_webdav(
        source_folder=args.source,
        base_webdav_url=args.webdav,
        label=args.label,
        metadata=metadata,
        username=args.username,
        contact_email=args.email,
        dry_run=args.dry_run
    )



# %% ../nbs/01_cli.ipynb 4
if __name__ == "__main__" and not hasattr(__builtins__, '__IPYTHON__'):
    main()

